import { getUserSettings, updateUserSettings, getSettingsChoices } from '@/services/api';
export default {
  data() {
    return {
      loading: true,
      settingsForm: {
        default_currency: '',
        use_default_currency_where_relevant: false,
        chart_frequency: '',
        chart_timeline: '',
        NAV_barchart_default_breakdown: '',
        digits: 0,
        custom_brokers: ''
      },
      currencyChoices: [],
      frequencyChoices: [],
      timelineChoices: [],
      navBreakdownChoices: [],
      brokerChoices: [],
      fieldErrors: {
        default_currency: [],
        use_default_currency_where_relevant: [],
        chart_frequency: [],
        chart_timeline: [],
        NAV_barchart_default_breakdown: [],
        digits: [],
        custom_brokers: []
      },
      snackbar: false,
      snackbarMessage: ''
    };
  },
  computed: {
    snackbarColor() {
      return this.snackbarMessage.toLowerCase().includes('error') ? 'error' : 'success';
    }
  },
  async mounted() {
    await this.loadData();
  },
  methods: {
    async loadData() {
      try {
        this.loading = true;
        const [settings, choices] = await Promise.all([getUserSettings(), getSettingsChoices()]);
        this.settingsForm = settings;
        this.currencyChoices = choices.currency_choices;
        this.frequencyChoices = choices.frequency_choices;
        this.timelineChoices = choices.timeline_choices;
        this.navBreakdownChoices = this.formatChoices(choices.nav_breakdown_choices);
        this.brokerChoices = this.formatChoices(choices.broker_choices);
      } catch (error) {
        console.error('Error loading settings data:', error);
        this.showErrorMessage('Failed to load settings. Please try again.');
      } finally {
        this.loading = false;
      }
    },
    formatChoices(choices) {
      return choices.map(choice => ({
        value: choice[0],
        title: choice[1]
      }));
    },
    async saveSettings() {
      try {
        const response = await updateUserSettings(this.settingsForm);
        if (response.success) {
          this.showSuccessMessage('Settings saved successfully');
        } else {
          this.handleFieldErrors(response.errors);
        }
      } catch (error) {
        console.error('Error saving settings:', error);
        this.showErrorMessage('Failed to save settings. Please try again.');
      }
    },
    handleFieldErrors(errors) {
      this.clearFieldErrors();
      Object.keys(errors).forEach(field => {
        if (field in this.fieldErrors) {
          this.fieldErrors[field] = errors[field];
        }
      });
      this.showErrorMessage('Please correct the errors in the form.');
    },
    clearFieldErrors() {
      Object.keys(this.fieldErrors).forEach(field => {
        this.fieldErrors[field] = [];
      });
    },
    showSuccessMessage(message) {
      this.snackbarMessage = message;
      this.snackbar = true;
    },
    showErrorMessage(message) {
      this.snackbarMessage = message;
      this.snackbar = true;
    }
  }
};
